<script>(function(){try{var t=localStorage.getItem('tuklas-theme');if(t!=='dark'&&t!=='light'){t=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}document.documentElement.dataset.theme=t;var m=localStorage.getItem('tuklas-reduce-motion');document.documentElement.dataset.reduceMotion=(m===null||m==='true'||matchMedia('(prefers-reduced-motion: reduce)').matches)?'true':'false'}catch(e){document.documentElement.dataset.theme='light';document.documentElement.dataset.reduceMotion='true'}})()</script>
